 public static void Frame(Graphics g,bool alarm,bool editing){g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;Box(g,new Rectangle(24,22,38,38),AppTheme.Selection,10);Center(g,alarm?"◷":"+",new Rectangle(24,22,38,38),23,Accent);T(g,editing?"Настроить событие":alarm?"Новый будильник":"Новое напоминание",23,Text,76,23,true);T(g,"LumaDesk  /  "+(alarm?"Время для важного":"Чтобы ничего не забыть"),11,Muted,77,53);
