 [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
 public static void DarkChrome(Form form){try{int dark=AppTheme.Light?0:1;DwmSetWindowAttribute(form.Handle,20,ref dark,4);int corner=2;DwmSetWindowAttribute(form.Handle,33,ref corner,4);}catch{}}
