public abstract class SmoothControl:Control {
 protected bool hover;protected SmoothControl(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Selectable,true);BackColor=EditorArt.Bg;Cursor=Cursors.Hand;TabStop=true;}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}protected override void OnGotFocus(EventArgs e){Invalidate();base.OnGotFocus(e);}protected override void OnLostFocus(EventArgs e){Invalidate();base.OnLostFocus(e);}
 protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Space||e.KeyCode==Keys.Enter){OnClick(EventArgs.Empty);e.Handled=true;e.SuppressKeyPress=true;}else base.OnKeyDown(e);}
 protected abstract void Draw(Graphics g);
 protected override void OnPaint(PaintEventArgs e){if(Width<1||Height<1)return;using(var image=new Bitmap(Width*2,Height*2,PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(image)){g.Clear(BackColor);g.ScaleTransform(2,2);g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;Draw(g);if(Focused&&ShowFocusCues)EditorArt.Box(g,new Rectangle(Width/2-10,Height-4,20,2),Color.FromArgb(132,148,207),1);}e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.PixelOffsetMode=PixelOffsetMode.HighQuality;e.Graphics.DrawImage(image,new Rectangle(0,0,Width,Height));}}
}
public class SmoothButton:SmoothControl {public bool Primary,Selected;public SmoothButton(string text,Rectangle bounds,EventHandler click){Text=text;Bounds=bounds;AccessibleRole=AccessibleRole.PushButton;Click+=click;}protected override void Draw(Graphics g){EditorArt.Button(g,new Rectangle(0,0,Width,Height),Text,Primary,hover,Selected);}}
public class MelodyCard:SmoothControl {public int Index;public bool Selected;public MelodyCard(int index,Rectangle bounds,EventHandler click){Index=index;Bounds=bounds;AccessibleRole=AccessibleRole.RadioButton;AccessibleName=Melodies.Names[index];Click+=click;}protected override void Draw(Graphics g){EditorArt.Melody(g,new Rectangle(0,0,Width,Height),Index,Selected,hover);}}
public class Switch:SmoothControl {public bool Value;public Switch(Rectangle bounds,bool value){Bounds=bounds;Value=value;AccessibleName="Событие включено";AccessibleRole=AccessibleRole.CheckButton;Click+=(s,e)=>{Value=!Value;Invalidate();};}protected override void Draw(Graphics g){EditorArt.Switch(g,new Rectangle(0,0,Width,Height),Value);}}
public class Stepper:SmoothControl {public int Value=5;public Stepper(Rectangle bounds,int value){Bounds=bounds;Value=Math.Max(1,Math.Min(120,value));AccessibleName="Отложить на минут";AccessibleRole=AccessibleRole.SpinButton;MouseClick+=(s,e)=>Change(e.X<Width/2?-1:1);}
 void Change(int d){Value=Math.Max(1,Math.Min(120,Value+d));Invalidate();}protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Up||e.KeyCode==Keys.Right){Change(1);e.Handled=true;}else if(e.KeyCode==Keys.Down||e.KeyCode==Keys.Left){Change(-1);e.Handled=true;}else base.OnKeyDown(e);}protected override void Draw(Graphics g){EditorArt.Field(g,new Rectangle(0,0,Width,Height));EditorArt.Center(g,"−",new Rectangle(0,0,34,Height),18,EditorArt.Accent);EditorArt.Center(g,Value.ToString(),new Rectangle(35,0,Width-70,Height),14,EditorArt.Text,true);EditorArt.Center(g,"+",new Rectangle(Width-34,0,34,Height),18,EditorArt.Accent);}}
public class DarkField:Panel {
 public TextBoxBase Input;public DarkField(Rectangle r,string text,string mask){Bounds=r;BackColor=EditorArt.Bg;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Input=mask==null?(TextBoxBase)new TextBox{MaxLength=100}:new MaskedTextBox{Mask=mask,PromptChar='_',AsciiOnly=true,Culture=CultureInfo.InvariantCulture,InsertKeyMode=InsertKeyMode.Overwrite};Input.BorderStyle=BorderStyle.None;Input.BackColor=EditorArt.Panel;Input.ForeColor=EditorArt.Text;Input.Font=new Font(Scene.FontName,11);Input.Text=text;Input.Bounds=new Rectangle(13,(r.Height-23)/2,r.Width-26,25);Input.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;Controls.Add(Input);Input.GotFocus+=(s,e)=>Invalidate();Input.LostFocus+=(s,e)=>Invalidate();}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;EditorArt.Field(e.Graphics,new Rectangle(0,0,Width,Height));if(Input.Focused)EditorArt.Border(e.Graphics,new Rectangle(0,0,Width-1,Height-1),EditorArt.Accent);}
}
public class CalendarPopup:ChromeForm {
 DateTime month,selected;Action<DateTime> chosen;
 public CalendarPopup(DateTime date,Action<DateTime> choose){month=new DateTime(date.Year,date.Month,1);selected=date.Date;chosen=choose;SetContentSize(300,310);Text="Выбрать дату";BackColor=EditorArt.Bg;ForeColor=EditorArt.Text;StartPosition=FormStartPosition.Manual;ShowInTaskbar=false;DoubleBuffered=true;KeyPreview=true;Deactivate+=(s,e)=>Close();KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)Close();};MouseClick+=(s,e)=>{int y=e.Y-CaptionHeight;if(y<0)return;if(y<49&&e.X>218){month=month.AddMonths(e.X<260?-1:1);Invalidate();return;}if(y>=78&&y<288&&e.X>=10&&e.X<290){int cell=(y-78)/35*7+(e.X-10)/40;var d=month.AddDays(cell-((int)month.DayOfWeek+6)%7);chosen(d);Close();}};}
 protected override void OnShown(EventArgs e){base.OnShown(e);EditorArt.DarkChrome(this);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;var saved=g.Save();g.TranslateTransform(0,CaptionHeight);g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;EditorArt.T(g,month.ToString("MMMM yyyy",Program.Ru),15,EditorArt.Text,14,18,true);EditorArt.Center(g,"‹",new Rectangle(221,9,35,35),23,EditorArt.Accent);EditorArt.Center(g,"›",new Rectangle(259,9,35,35),23,EditorArt.Accent);var names=new[]{"ПН","ВТ","СР","ЧТ","ПТ","СБ","ВС"};for(int i=0;i<7;i++)EditorArt.Center(g,names[i],new Rectangle(10+i*40,53,36,22),10,EditorArt.Muted);for(int i=0;i<42;i++){var d=month.AddDays(i-((int)month.DayOfWeek+6)%7);var r=new Rectangle(10+i%7*40,78+i/7*35,36,31);if(d==selected)EditorArt.Box(g,r,AppTheme.Primary,7);EditorArt.Center(g,d.Day.ToString(),r,13,d==selected?Color.White:d.Month==month.Month?EditorArt.Text:AppTheme.Muted,d==selected);}g.Restore(saved);}}
public class EditorForm:ChromeForm {
 public Item Result;Item original;string kind,sound;DarkField title,date,time;SmoothButton[] days=new SmoothButton[7];MelodyCard[] cards=new MelodyCard[3];Switch enabled;Stepper snooze;SmoothButton preview;MelodyPlayer player=new MelodyPlayer();Timer previewTimer=new Timer();Label status;bool previewing;
 public EditorForm(Item item,string eventKind,DateTime? day){original=item;kind=eventKind;sound=item==null?Melodies.Ids[0]:string.IsNullOrEmpty(item.Sound)?Melodies.Ids[0]:item.Sound;Text="LumaDesk · "+(kind=="alarm"?"Будильник":"Напоминание");SetContentSize(520,681);Font=Theme.F(10);BackColor=EditorArt.Bg;ForeColor=EditorArt.Text;StartPosition=FormStartPosition.CenterScreen;MaximizeBox=false;MinimizeBox=false;DoubleBuffered=true;KeyPreview=true;
 DateTime initial=item!=null?item.Next:day.HasValue?day.Value.Date.AddHours(9):DateTime.Now.AddMinutes(5);title=new DarkField(new Rectangle(24,122,472,43),item==null?(kind=="alarm"?"Будильник":"Напоминание"):item.Title,null);date=new DarkField(new Rectangle(24,201,228,44),initial.ToString("dd.MM.yyyy"),"00.00.0000");time=new DarkField(new Rectangle(268,201,228,44),initial.ToString("HH:mm"),"00:00");title.Input.AccessibleName="Название события";date.Input.AccessibleName="Дата дд.мм.гггг";time.Input.AccessibleName="Время часы минуты";Controls.AddRange(new Control[]{title,date,time});date.Input.Width=159;
 var calendar=new SmoothButton("▦",new Rectangle(185,7,35,30),(s,e)=>PickDate());calendar.Font=Theme.F(12);calendar.BackColor=EditorArt.Panel;calendar.AccessibleName="Выбрать дату в календаре";date.Controls.Add(calendar);
 string[] labels={"ПН","ВТ","СР","ЧТ","ПТ","СБ","ВС"};for(int i=0;i<7;i++){int index=i;days[i]=new SmoothButton(labels[i],new Rectangle(24+i*68,292,64,37),(s,e)=>{days[index].Selected=!days[index].Selected;days[index].Invalidate();});days[i].Selected=item!=null&&(item.Days&(1<<((i+1)%7)))!=0;days[i].AccessibleRole=AccessibleRole.CheckButton;days[i].AccessibleName=labels[i];Controls.Add(days[i]);}
 for(int i=0;i<3;i++){int index=i;cards[i]=new MelodyCard(i,new Rectangle(24+i*161,376,150,72),(s,e)=>ChooseSound(Melodies.Ids[index]));Controls.Add(cards[i]);}
 preview=new SmoothButton("▶  Прослушать",new Rectangle(24,461,172,34),(s,e)=>Preview());var custom=new SmoothButton("Свой WAV",new Rectangle(206,461,140,34),(s,e)=>{using(var f=new OpenFileDialog{Filter="Звуковой файл WAV|*.wav",Title="Мелодия события"})if(f.ShowDialog(this)==DialogResult.OK)ChooseSound(f.FileName);});Controls.Add(preview);Controls.Add(custom);
 status=new Label{Bounds=new Rectangle(25,505,470,23),BackColor=EditorArt.Bg,ForeColor=EditorArt.Muted,Font=Theme.F(9),AutoEllipsis=true};Controls.Add(status);snooze=new Stepper(new Rectangle(164,535,122,32),item==null?5:item.Snooze);enabled=new Switch(new Rectangle(441,538,54,26),item==null||item.Enabled);Controls.Add(snooze);Controls.Add(enabled);
 Controls.Add(new SmoothButton("Отмена",new Rectangle(24,605,143,40),(s,e)=>{DialogResult=DialogResult.Cancel;Close();}));var save=new SmoothButton("Сохранить",new Rectangle(179,605,317,40),(s,e)=>Save()){Primary=true};Controls.Add(save);previewTimer.Tick+=(s,e)=>StopPreview();FormClosing+=(s,e)=>StopPreview();KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape){DialogResult=DialogResult.Cancel;Close();}else if(e.Control&&e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;e.Handled=true;Save();}};UpdateSound();}
 protected override void OnShown(EventArgs e){base.OnShown(e);EditorArt.DarkChrome(this);title.Input.Focus();title.Input.SelectAll();}
