 void PickDate(){DateTime value;if(!DateTime.TryParseExact(date.Input.Text,"dd.MM.yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out value))value=DateTime.Today;var popup=new CalendarPopup(value,d=>date.Input.Text=d.ToString("dd.MM.yyyy"));var point=date.PointToScreen(new Point(0,date.Height+5));var screen=Screen.FromPoint(point).WorkingArea;popup.Location=new Point(Math.Max(screen.Left,Math.Min(point.X,screen.Right-popup.Width)),point.Y+popup.Height>screen.Bottom?date.PointToScreen(Point.Empty).Y-popup.Height:point.Y);popup.Show(this);}
 void ChooseSound(string value){StopPreview();sound=value;UpdateSound();}
 void UpdateSound(){int selected=Melodies.Index(sound);for(int i=0;i<3;i++){cards[i].Selected=selected==i;cards[i].Invalidate();}status.ForeColor=EditorArt.Muted;status.Text=selected>=0?"Выбрано: "+Melodies.Names[selected]:"Свой файл: "+Path.GetFileName(sound);}
 void Preview(){if(previewing){StopPreview();return;}try{player.Play(sound,false);previewing=true;preview.Text="■  Остановить";preview.Invalidate();previewTimer.Interval=Melodies.Duration(sound)+100;previewTimer.Start();UpdateSound();}catch{StopPreview();Error("Не удалось проиграть мелодию. Проверь WAV-файл и звук Windows.");}}
 void StopPreview(){previewTimer.Stop();player.Stop();previewing=false;if(preview!=null){preview.Text="▶  Прослушать";preview.Invalidate();}}
 void Error(string message){status.ForeColor=AppTheme.Error;status.Text=message;}
 void Save(){DateTime d,t;if(string.IsNullOrWhiteSpace(title.Input.Text)){Error("Напиши название события.");title.Input.Focus();return;}if(!DateTime.TryParseExact(date.Input.Text,"dd.MM.yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out d)){Error("Проверь дату: дд.мм.гггг.");date.Input.Focus();return;}if(!DateTime.TryParseExact(time.Input.Text,"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out t)){Error("Проверь время: часы от 00 до 23, минуты от 00 до 59.");time.Input.Focus();return;}int mask=0;for(int i=0;i<7;i++)if(days[i].Selected)mask|=1<<((i+1)%7);var a=new Item{Id=original==null?Guid.NewGuid().ToString():original.Id,Title=title.Input.Text.Trim(),Kind=kind,Days=mask,Next=d.Date.AddHours(t.Hour).AddMinutes(t.Minute),Sound=sound,Snooze=snooze.Value,Enabled=enabled.Value};if(mask!=0)a.Next=Host.Advance(a,a.Next>DateTime.Now?a.Next.AddTicks(-1):DateTime.Now);else if(a.Enabled&&a.Next<=DateTime.Now){Error("Выбери дату и время в будущем.");return;}if(Melodies.Index(sound)<0&&!File.Exists(sound)){Error("WAV-файл не найден. Выбери другую мелодию.");return;}Result=a;StopPreview();DialogResult=DialogResult.OK;Close();}
 protected override void Dispose(bool disposing){if(disposing){previewTimer.Dispose();player.Dispose();}base.Dispose(disposing);}
}
